            ptr->TAT = tat;
        }
        return;
    }
    // else traverse the queue and update the values
    while (ptr != NULL && ptr->ID != id)
    {
        ptr = ptr->next;
    }
    if (ptr != NULL && ct != 0)
    {
        ptr->CT = ct;
    }
    if (ptr != NULL && wt != 0)
    {
        ptr->WT = wt;
    }
    if (ptr != NULL && tat != 0)
    {
        ptr->TAT = tat;
    }
    return;
}


